async function loadRemainingTransactions(){
 const token=++txLoadToken;
 while(txCursor&&token===txLoadToken){
  const d=await api('/api/ledger?limit=200&cursor='+encodeURIComponent(txCursor));
  if(token!==txLoadToken)return;
  applyLedgerData({transactions:items.concat(d.transactions||[])});
  txCursor=d.nextCursor||null;
 }
 if(token===txLoadToken&&['transactions','investments'].includes(activeView))renderView(activeView);
}
