function updateNav(view){const tools=$("toolsToggle");if(tools)tools.classList.toggle("active",TOOL_VIEWS.includes(view));setToolsMenu(false);document.querySelectorAll("[data-owner-only]").forEach(b=>b.classList.toggle("hidden",user?.role!=="admin"));const banksBtn=document.querySelector("#menuNav [data-view=banks]");if(banksBtn&&view==="bank-detail")banksBtn.classList.add("active");let n=0;try{n=alertPaymentItems().length+rewardAlertItems().length}catch{}document.querySelectorAll("[data-alert-badge]").forEach(b=>{b.textContent=n>9?"9+":String(n);b.classList.toggle("hidden",!n);b.setAttribute("aria-label",n+" payment alert"+(n===1?"":"s"))})}
