function accountKey(label){const x=String(label||'').toLowerCase().replace(/[•·]/g,' ').replace(/\s+/g,' ').trim();const sections=accountingTemplate?.sections||[];const reward=sections.find(s=>s.key==='rewards');if((reward?.assets||[]).some(a=>x.includes(String(a).toLowerCase())))return null;const aliases=accountingTemplate?.accountAliases||{};for(const [canonical,names] of Object.entries(aliases)){if([canonical,...names].some(a=>x.includes(String(a).toLowerCase())))return canonical}if(/\bmonies\b|reward coins|reward points|cashback coins/.test(x))return null;return String(label||'Other account').trim();}
// Saved records for ONE bank's detail page. A record about that bank alone is shown whole; a combined record
// (several banks in one table) keeps the header plus only this bank's rows and notes. Investment records are never
// shown on a bank page (e.g. "HDFC Bank" is also a stock). Atom rows belong to Atom, not Slice.
const BANK_MATCH={'slice':/\bslice\b/i,'atom':/\batom\b/i,'hdfc bank':/\bhdfc\b/i,'bank of india':/bank of india|\bboi\b/i,'roarbank':/roar\s?bank/i,'fixed deposits':/fixed deposit/i};
const NOT_BANK_RECORD=/equity|holdings|demat|mutual fund|angel ?one|stock advisor|market price/i;
function bankMatches(k,text){const re=BANK_MATCH[k]||new RegExp(k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i');if(!re.test(text))return false;return k==='slice'?!/\batom\b/i.test(text)||/slice savings|slice credit/i.test(text):true}
function accountRecords(key){
 const k=String(key||'').toLowerCase();
 const otherBank=text=>Object.entries(BANK_MATCH).some(([o,re])=>o!==k&&o!=='fixed deposits'&&re.test(text)&&!(k==='slice'&&o==='atom'&&/slice savings|slice credit/i.test(text)));
 const out=[];
 sourceSections.forEach(s=>{
  const heading=String(s.heading||'');
  if(NOT_BANK_RECORD.test(heading))return;
  const all=heading+' '+(s.tables||[]).flat().flat().join(' ')+' '+(s.notes||[]).join(' ');
  if(!(BANK_MATCH[k]||new RegExp(k,'i')).test(all))return;
  if(bankMatches(k,heading)&&!otherBank(heading)){out.push(s);return}          // a record about this bank alone
  const tables=(s.tables||[]).map(rows=>rows.length?[rows[0],...rows.slice(1).filter(r=>bankMatches(k,r.join(' ')))]:rows).filter(rows=>rows.length>1);
  const notes=(s.notes||[]).filter(n=>bankMatches(k,String(n)));
  if(tables.length||notes.length)out.push({...s,tables,notes,_filtered:true});
 });
 return out;
}
