function moreHubHtml(){const banks=sourceSections.filter(isBankBalanceSection).length;const other=sourceSections.filter(s=>!isBankBalanceSection(s)&&!isInvestmentRecord(s)).length;const due=plannedBills.filter(b=>b.status==='planned').length;const rows=[{group:'YOUR MONEY',items:[['banks','Bank accounts','Balances, account snapshots and details','▣',banks],['investments','Investments','Stocks, mutual funds and metals','↗',null],['other','Records','Statements, screenshots and reports','◫',recSnapshots().length]]},{group:'ACTIVITY & REMINDERS',items:[['transactions','Transactions','Income, spending and transfers','≡',transactionTotalCount()],['interest','Interest','Slice Savings, Atom and fixed-deposit earnings','₹',interestRows.length],['rewards','Rewards','Points, coins and cashback','★',null],['alerts','Alerts & bills','Upcoming payments and reminders','!',due],['subscriptions','Subscriptions & mandates','Recurring payments and authorisations','⟳',subscriptions.length]]},{group:'TOOLS',items:[['stock-advisor','Stock Advisor','Research and portfolio signals for Indian stocks','⌁',null],['angel-one','Angel One','Live broker holdings','◈',null],['data-quality','Data quality','Open data issues and the v1 ↔ v2 check (owner)','✓',null]]}];return '<section class="more-hub"><div class="more-welcome"><div class="eyebrow">QUICK ACCESS</div><h3>Everything in one place</h3><p>Choose what you want to review. Your saved financial records stay unchanged.</p></div>'+rows.map(g=>'<section class="more-group"><h4>'+g.group+'</h4><div class="more-list">'+g.items.map(x=>'<button type="button" class="more-link" data-view="'+x[0]+'"><span class="more-link-icon">'+x[3]+'</span><span class="more-link-copy"><b>'+x[1]+'</b><small>'+x[2]+'</small></span>'+(x[4]===null?'':'<span class="more-link-count">'+x[4]+'</span>')+'<span class="more-link-arrow">›</span></button>').join('')+'</div></section>').join('')+'<section class="more-group"><h4>ACCOUNT</h4><div class="more-list">'+(user?.role==='admin'?'<button type="button" class="more-link" data-action="reset-password"><span class="more-link-icon">⚿</span><span class="more-link-copy"><b>Reset a password</b><small>Owner only · signs that account out everywhere</small></span><span class="more-link-arrow">›</span></button><a class="more-link" href="'+(wantModelV1()?'?':'?model=v1')+'"><span class="more-link-icon">⇄</span><span class="more-link-copy"><b>'+(wantModelV1()?'Back to the v2 dashboard':'Compare with old dashboard (v1)')+'</b><small>Owner only · v2 (account model) is the default</small></span><span class="more-link-arrow">›</span></a>':'')+'<a class="more-link" href="/api/clear-session"><span class="more-link-icon">↻</span><span class="more-link-copy"><b>Clear session</b><small>Clear this browser login session</small></span><span class="more-link-arrow">›</span></a><button type="button" class="more-link" data-action="logout"><span class="more-link-icon">⇥</span><span class="more-link-copy"><b>Sign out</b><small>End your current account session</small></span><span class="more-link-arrow">›</span></button></div></section><div class="more-footnote"><span>●</span> '+sourceSections.length+' imported sections · '+transactionTotalCount()+' ledger entries · data preserved</div></section>'}
// Records page (2026-11-11): every saved statement, screenshot and report (wealth_snapshots) with all its data.
let recordsState={q:'',type:'all'};
const REC_TYPES=[['all','All'],['statement','Statements'],['screenshot','Screenshots'],['holdings','Holdings'],['report','Reports'],['note','Notes']];
const REC_LABEL={statement:'Statement',screenshot:'Screenshot',holdings:'Holdings',report:'Report',note:'Note'};
const REC_HIDE=new Set(['sections','source','snapshotDate','importedAt','kind','client_code','section']);
function recSnapshots(){return (typeof window!=='undefined'&&window.__wealthSnapshots)||[]}
function recPayload(x){let p=x.payload;if(typeof p==='string'){try{p=JSON.parse(p)}catch{p={}}}return p&&typeof p==='object'&&!Array.isArray(p)?p:{}}
function recType(x){const n=String(x.source_name||'').toLowerCase();return /screenshot/.test(n)?'screenshot':/holding|portfolio/.test(n)?'holdings':/report|p&l|advisor|prices|analy[sz]er/.test(n)?'report':/clarification|update/.test(n)?'note':'statement'}
function recTitle(x){return String(x.source_name||'Record').replace(/\s+[—-]\s+\d{1,2}\s+[A-Za-z]+\s+\d{4}(\s+[\d:]+\s*IST)?(\s+session)?$/,'').trim()||'Record'}
function recDate(d){return d?new Date(d+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'No date'}
function recHuman(k){return String(k).replace(/_/g,' ').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/\binr\b/i,'(₹)').replace(/\bpct\b/i,'%').replace(/\s+/g,' ').trim().replace(/^\w/,c=>c.toUpperCase())}
function recScalar(k,v){if(v==null||v==='')return '—';if(typeof v==='boolean')return v?'Yes':'No';if(typeof v==='number')return v.toLocaleString('en-IN',{maximumFractionDigits:2})+(/pct|percent/i.test(k)?'%':'');return String(v)}
function recValueHtml(k,v,depth){
 if(depth>3)return '<code>'+esc(JSON.stringify(v))+'</code>';
 if(Array.isArray(v)){
  if(!v.length)return '<span class="muted">None</span>';
  if(v.every(e=>e&&typeof e==='object'&&!Array.isArray(e))){const cols=[...new Set(v.flatMap(o=>Object.keys(o)))].filter(c=>!REC_HIDE.has(c)).slice(0,10);
   return '<div class="snapshot-table-wrap"><table class="snapshot-table rec-table"><thead><tr>'+cols.map(c=>'<th>'+esc(recHuman(c))+'</th>').join('')+'</tr></thead><tbody>'+v.map(o=>'<tr>'+cols.map(c=>'<td>'+(o[c]&&typeof o[c]==='object'?esc(JSON.stringify(o[c])):esc(recScalar(c,o[c])))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
  if(v.every(e=>Array.isArray(e)))return '<div class="snapshot-table-wrap"><table class="snapshot-table"><tbody>'+v.map((r,i)=>'<tr>'+r.map(c=>i?'<td>'+esc(c)+'</td>':'<th>'+esc(c)+'</th>').join('')+'</tr>').join('')+'</tbody></table></div>';
  return '<ul class="snapshot-notes">'+v.map(e=>'<li>'+(e&&typeof e==='object'?recObjectHtml(e,depth+1):esc(recScalar(k,e)))+'</li>').join('')+'</ul>'}
 if(v&&typeof v==='object')return recObjectHtml(v,depth+1);
 return esc(recScalar(k,v))}
function recObjectHtml(o,depth){depth=depth||0;const keys=Object.keys(o).filter(k=>!REC_HIDE.has(k));if(!keys.length)return '';
 const simple=keys.filter(k=>o[k]==null||typeof o[k]!=='object'),nested=keys.filter(k=>o[k]!=null&&typeof o[k]==='object');
 return (simple.length?'<dl class="rec-kv">'+simple.map(k=>'<div><dt>'+esc(recHuman(k))+'</dt><dd>'+recValueHtml(k,o[k],depth)+'</dd></div>').join('')+'</dl>':'')
  +nested.map(k=>'<div class="rec-block'+(depth?' rec-nested':'')+'"><h5>'+esc(recHuman(k))+'</h5>'+recValueHtml(k,o[k],depth)+'</div>').join('')}
function recFacts(p){const src=[p.summary,p.totals,p.statementSummary,p].find(o=>o&&typeof o==='object'&&!Array.isArray(o)&&Object.entries(o).some(([k,v])=>typeof v==='number'&&!REC_HIDE.has(k)))||{};
 return Object.entries(src).filter(([k,v])=>typeof v==='number'&&!REC_HIDE.has(k)).slice(0,3).map(([k,v])=>'<span><small>'+esc(recHuman(k))+'</small><b>'+esc(recScalar(k,v))+'</b></span>').join('')}
function recCounts(p){const parts=[];const secs=Array.isArray(p.sections)?p.sections.length:0;if(secs)parts.push(secs+' section'+(secs>1?'s':''));
 Object.entries(p).filter(([k,v])=>k!=='sections'&&Array.isArray(v)&&v.length&&v[0]&&typeof v[0]==='object').forEach(([k,v])=>parts.push(v.length+' '+recHuman(k).toLowerCase()));return parts.join(' · ')}
function recordsItems(){const s=recordsState,q=s.q.trim().toLowerCase();
 return recSnapshots().map(x=>({x,p:recPayload(x),type:recType(x)}))
  .filter(r=>(s.type==='all'||r.type===s.type)&&(!q||(String(r.x.source_name||'')+' '+JSON.stringify(r.p)).toLowerCase().includes(q)))
  .sort((a,b)=>String(b.x.snapshot_date||'').localeCompare(String(a.x.snapshot_date||''))||String(b.x.created_at||'').localeCompare(String(a.x.created_at||'')))}
function recordCardHtml(r){const d=String(r.x.snapshot_date||'').slice(0,10),p=r.p,secs=Array.isArray(p.sections)?p.sections:[];
 const src=typeof p.source==='string'&&p.source!==r.x.source_name?p.source.slice(0,70):'';
 const body=secs.map(s=>'<section class="rec-section"><h5>'+esc(s.heading||'Section')+'</h5>'+sectionContent(s)+'</section>').join('')+recObjectHtml(p,0);
 return '<details class="rec-card"><summary><span class="rec-type rec-'+r.type+'">'+REC_LABEL[r.type]+'</span><span class="rec-main"><b>'+esc(recTitle(r.x))+'</b><small>'+esc([recDate(d),src,recCounts(p)].filter(Boolean).join(' · '))+'</small></span><span class="rec-facts">'+recFacts(p)+'</span><i class="rec-chev" aria-hidden="true">›</i></summary><div class="rec-body">'+(body||'<p class="muted">No details saved.</p>')+'</div></details>'}
function recordsListHtml(items){if(!items.length)return '<div class="interest-empty"><b>No records match</b><p>Try another word or type.</p></div>';
 const groups=[];items.forEach(r=>{const d=String(r.x.snapshot_date||'').slice(0,10);const m=d?new Date(d+'T00:00:00').toLocaleDateString('en-IN',{month:'long',year:'numeric'}):'No date';const g=groups[groups.length-1];if(g&&g.m===m)g.items.push(r);else groups.push({m,items:[r]})});
 return groups.map(g=>'<div class="rec-group"><h4>'+esc(g.m)+' <em>'+g.items.length+'</em></h4>'+g.items.map(recordCardHtml).join('')+'</div>').join('')}
function recordsPageHtml(){const all=recSnapshots(),s=recordsState,counts={};all.forEach(x=>{const t=recType(x);counts[t]=(counts[t]||0)+1});
 const latest=all.map(x=>String(x.snapshot_date||'').slice(0,10)).filter(Boolean).sort().pop();
 return '<section class="rec-page"><div class="rec-head"><div><span class="interest-kicker">TOOLS</span><h3>Statements &amp; records</h3><p>Everything you shared with the app — statements, screenshots and reports — with the data saved from each. Read-only: totals come from your accounts and holdings, not from here.</p></div><div class="rec-stats"><span><b>'+all.length+'</b><small>records</small></span><span><b>'+esc(latest?recDate(latest):'—')+'</b><small>latest</small></span></div></div>'
  +'<div class="rec-toolbar"><label class="activity-search"><span>⌕</span><input id="recordsSearch" type="search" placeholder="Search records — e.g. Slice, EPF, holdings…" autocomplete="off" value="'+esc(s.q)+'"></label><div class="rec-chips">'+REC_TYPES.filter(([k])=>k==='all'||counts[k]).map(([k,l])=>'<button type="button" class="rec-chip'+(s.type===k?' active':'')+'" data-record-type="'+k+'" aria-pressed="'+(s.type===k)+'">'+l+' <em>'+(k==='all'?all.length:counts[k])+'</em></button>').join('')+'</div></div>'
  +'<div id="recordsList">'+recordsListHtml(recordsItems())+'</div></section>'}
// Rewards page (2026-11-11, Plan 4 Part A): points, coins and cashback, kept apart from net worth.
