 return '<div class="rw-page"><div class="rw-top"><div><span class="interest-kicker">REWARDS</span><h3>Rewards &amp; points</h3><p>Points, coins and cashback · shown apart from net worth</p></div><div class="rw-total"><strong>'+money(t.value)+'</strong><small>points value · '+t.valuedPrograms+' of '+(t.valuedPrograms+t.unvaluedPrograms)+' programs priced</small></div></div>'
