// Reward alerts (Plan 4, TR4-A.8): ready to redeem, within 10 % of the redemption threshold, or expiring within 30 days.
function rewardAlertItems(){const d=rewardsData;if(!d||!Array.isArray(d.programs))return [];const today=new Date();today.setHours(0,0,0,0);const out=[];
 d.programs.forEach(p=>{if(p.min_redeem&&p.units!=null){if(p.toRedeem===0)out.push({p,kind:'ready',text:'Ready to redeem — '+rwUnits(p.units)+' '+p.unit+(p.value!=null?' ≈ '+money(p.value):'')});else if(p.toRedeem>0&&p.toRedeem<=p.min_redeem*0.1)out.push({p,kind:'near',text:rwUnits(p.toRedeem)+' '+p.unit+' more to redeem ('+rwUnits(p.units)+' of '+rwUnits(p.min_redeem)+')'})}
  if(p.expires_on){const days=Math.round((new Date(p.expires_on+'T00:00:00')-today)/864e5);if(days>=0&&days<=30)out.push({p,kind:'expiring',text:rwUnits(p.units)+' '+p.unit+' expire '+(days===0?'today':'in '+days+' day'+(days===1?'':'s'))})}});
 return out}
function rewardAlertsHtml(){const items=rewardAlertItems();if(!items.length)return '';
 return '<section class="chart-card planned-bills"><div class="chart-head"><div><h4>Rewards</h4><p>Ready to redeem, close to the threshold, or expiring soon</p></div><span class="pill">'+items.length+'</span></div><div class="planned-bill-list">'
  +items.map(a=>'<article class="planned-bill-row"><div class="planned-bill-main"><b>'+esc(a.p.name)+'</b><small>'+esc(a.text)+'</small>'+(a.p.redeem_note?'<small>'+esc(a.p.redeem_note)+'</small>':'')+'</div><div class="planned-bill-actions"><button type="button" class="ghost" data-view="rewards">Open</button></div></article>').join('')+'</div></section>'}
function rewardsTileHtml(){const d=rewardsData;if(!d)return '';const c=d.cashback||{};
 return '<button type="button" class="mini-card rw-tile" data-view="rewards"><small>REWARDS &amp; CASHBACK</small><strong>'+money(d.totals.value)+'</strong><span>points value · cashback this month '+money(c.month||0)+'</span><span class="rw-tile-link">Open rewards →</span></button>'}
// Activity page (2026-11-11): period totals, readable day/month groups, safe delete, paging; filters survive background loading.
let activityState={q:'',kind:'all',account:'all',from:null,to:null,shown:60,sig:''};
function actYmd(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function activityPresetRange(v){const t=new Date(),f=new Date();if(v==='today')return [actYmd(t),actYmd(t)];if(v==='7'||v==='30'||v==='90'){f.setDate(f.getDate()-Number(v)+1);return [actYmd(f),actYmd(t)]}if(v==='month')return [actYmd(new Date(t.getFullYear(),t.getMonth(),1)),actYmd(t)];if(v==='lastmonth')return [actYmd(new Date(t.getFullYear(),t.getMonth()-1,1)),actYmd(new Date(t.getFullYear(),t.getMonth(),0))];return ['','']}
const ACT_PERIODS=[['month','This month'],['lastmonth','Last month'],['90','3 months'],['all','All time']];
function activityPeriod(from,to){for(const v of ['month','lastmonth','90','today','7','30']){const r=activityPresetRange(v);if(r[0]===from&&r[1]===to)return v}return !from&&!to?'all':'custom'}
const ACT_KIND={income:['Money in','↙','in'],expense:['Money out','↗','out'],transfer:['Transfer','⇄','tr'],investment:['Investment','⌁','inv'],liability:['Liability','₹','out']};
function actDayLabel(date){const t=actYmd(new Date()),y=actYmd(new Date(Date.now()-864e5));if(date===t)return 'Today';if(date===y)return 'Yesterday';const d=new Date(date+'T00:00:00');return Number.isFinite(d.getTime())?d.toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'}):date}
function actMonthLabel(m){const d=new Date(m+'-01T00:00:00');return Number.isFinite(d.getTime())?d.toLocaleDateString('en-IN',{month:'long',year:'numeric'}):m}
// Same split as the account details page: in = income; out = expense + investment + liability; transfers separate.
function actFlows(rows){const s=k=>rows.filter(x=>x.kind===k).reduce((n,x)=>n+Number(x.amount||0),0);const inn=s('income'),invest=s('investment'),liab=s('liability'),out=s('expense')+invest+liab;return {inn,out,net:inn-out,transfer:s('transfer'),invest,liab}}
function actSigned(x){const k=ACT_KIND[x.kind]||['',' ','tr'];return (k[2]==='in'?'+':k[2]==='out'||k[2]==='inv'?'−':'')+money(Number(x.amount||0))}
function activityRowsHtml(){
 const q=String($('activitySearch')?.value||'').trim().toLowerCase(),kind=$('activityKind')?.value||'all',account=$('activityAccount')?.value||'all',from=$('activityFrom')?.value||'',to=$('activityTo')?.value||'';
 const sig=[q,kind,account,from,to].join('|');activityState={...activityState,q,kind,account,from,to,shown:sig===activityState.sig?activityState.shown:60,sig};
 const period=activityPeriod(from,to);
 const rows=items.filter(x=>{const date=String(x.occurred_on||'').slice(0,10),hay=[x.category,x.description,x.account,x.kind,x.amount].join(' ').toLowerCase();return (kind==='all'||x.kind===kind)&&(account==='all'||(account==='__none'?x.account_id==null:String(x.account||'')===account))&&(!from||date>=from)&&(!to||date<=to)&&(!q||hay.includes(q))}).sort((a,b)=>String(b.occurred_on).localeCompare(String(a.occurred_on))||String(b.created_key||'').localeCompare(String(a.created_key||'')));
 const total=txCursor?transactionTotalCount():items.length;
 const count=$('activityCount');if(count)count.textContent=rows.length+' of '+total+(txCursor?' · loading older…':'');
 const filterCount=(kind!=='all'?1:0)+(account!=='all'?1:0)+(period==='custom'?1:0);const filterBadge=$('activityFilterBadge');if(filterBadge){filterBadge.textContent=filterCount;filterBadge.hidden=!filterCount}
 document.querySelectorAll('[data-activity-kind]').forEach(b=>b.classList.toggle('active',b.dataset.activityKind===kind));
 document.querySelectorAll('[data-activity-date]').forEach(b=>b.classList.toggle('active',b.dataset.activityDate===period));
 const active=[];if(kind!=='all')active.push({id:'activityKind',label:(ACT_KIND[kind]||[kind])[0]});if(account!=='all')active.push({id:'activityAccount',label:account==='__none'?'No account':account});if(period==='custom')active.push({id:'activityDate',label:(from||'Any date')+' – '+(to||'Today')});
 const chips=$('activityActiveFilters');if(chips)chips.innerHTML=active.map(x=>'<button type="button" class="activity-filter-chip" data-clear-filter="'+x.id+'">'+esc(x.label)+' <span>×</span></button>').join('');
 const clear=$('activityClearAll');if(clear)clear.hidden=active.length===0&&!q;
 const f=actFlows(rows),periodLabel=(ACT_PERIODS.find(p=>p[0]===period)||[0,period==='custom'?'Selected dates':period==='today'?'Today':'Last '+period+' days'])[1];
 const sum=$('activitySummary');if(sum)sum.innerHTML='<div class="act-tile in"><small>Money in</small><b>+'+esc(money(f.inn))+'</b></div><div class="act-tile out"><small>Money out</small><b>−'+esc(money(f.out))+'</b>'+(f.invest||f.liab?'<em>incl. '+[f.invest?'investments '+money(f.invest):'',f.liab?'card payments '+money(f.liab):''].filter(Boolean).join(' · ')+'</em>':'')+'</div><div class="act-tile net '+(f.net>=0?'pos':'neg')+'"><small>Net · '+esc(periodLabel)+'</small><b>'+(f.net>=0?'+':'−')+esc(money(Math.abs(f.net)))+'</b></div><div class="act-tile tr"><small>Transfers</small><b>'+esc(money(f.transfer))+'</b><em>between your accounts</em></div>';
 const target=$('activityRows');if(!target)return;
 if(!rows.length){target.innerHTML='<div class="activity-empty"><span>⌕</span><b>No transactions found</b><p>'+(period!=='all'?'Nothing in '+esc(periodLabel.toLowerCase())+'. Try “All time” or ':'Try another search or ')+'clear your filters.</p><button type="button" class="ghost" id="activityReset">Clear filters</button></div>';return}
 const shown=rows.slice(0,activityState.shown);
 const months=[];shown.forEach(x=>{const date=String(x.occurred_on||'').slice(0,10)||'Undated',m=date.slice(0,7);let mo=months[months.length-1];if(!mo||mo.m!==m){mo={m,days:[]};months.push(mo)}let d=mo.days[mo.days.length-1];if(!d||d.date!==date){d={date,rows:[]};mo.days.push(d)}d.rows.push(x)});
 const monthTotals=m=>actFlows(rows.filter(x=>String(x.occurred_on||'').slice(0,7)===m));
 const row=x=>{const k=ACT_KIND[x.kind]||[x.kind,'•','tr'];const noAcct=x.account_id==null;
  return '<details class="act-row"><summary><span class="act-icon '+k[2]+'">'+k[1]+'</span><span class="act-copy"><b>'+esc(x.description||x.category||k[0])+'</b><small>'+esc(x.category||k[0])+' · '+(noAcct?'<span class="act-noacct">No account</span>':esc(x.account))+'</small></span><span class="act-amt '+k[2]+'">'+esc(actSigned(x))+'</span></summary>'
  +'<div class="act-more"><dl><div><dt>Date</dt><dd>'+esc(actDayLabel(String(x.occurred_on).slice(0,10)))+' · '+esc(String(x.occurred_on).slice(0,10))+'</dd></div><div><dt>Type</dt><dd>'+esc(k[0])+'</dd></div><div><dt>Category</dt><dd>'+esc(x.category||'—')+'</dd></div><div><dt>Account</dt><dd>'+(noAcct?'Not linked to an account':esc(x.account))+'</dd></div>'+(x.description?'<div><dt>Note</dt><dd>'+esc(x.description)+'</dd></div>':'')+'</dl><button type="button" class="delete act-delete" data-id="'+esc(x.id)+'">Delete entry</button></div></details>'};
 target.innerHTML=months.map(mo=>{const t=monthTotals(mo.m);return '<section class="act-month"><div class="act-month-head"><b>'+esc(actMonthLabel(mo.m))+'</b><span><em class="in">+'+esc(money(t.inn))+'</em><em class="out">−'+esc(money(t.out))+'</em></span></div>'
  +mo.days.map(d=>{const dt=actFlows(d.rows);return '<div class="act-day"><div class="act-day-head"><span>'+esc(actDayLabel(d.date))+'</span><span>'+(dt.inn?'<em class="in">+'+esc(money(dt.inn))+'</em>':'')+(dt.out?'<em class="out">−'+esc(money(dt.out))+'</em>':'')+'</span></div>'+d.rows.map(row).join('')+'</div>'}).join('')+'</section>'}).join('')
  +(rows.length>shown.length?'<button type="button" class="ghost act-more-btn" id="activityMore">Show more · '+(rows.length-shown.length)+' left</button>':'');
}
function activitiesHtml(){
 const s=activityState,init=s.from===null?activityPresetRange('month'):[s.from,s.to];
 const kinds=[['all','All types'],['income','Money in'],['expense','Money out'],['transfer','Transfers'],['investment','Investments'],['liability','Liabilities']];
 const accountsList=[...new Set(items.filter(x=>x.account_id!=null).map(x=>String(x.account||'')).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
 const opt=(v,l,cur)=>'<option value="'+esc(v)+'"'+(v===cur?' selected':'')+'>'+esc(l)+'</option>';
 return '<section class="activity-card act-page"><div class="act-toolbar"><span id="activityCount" class="pill">'+items.length+' transactions</span><button type="button" class="primary" data-add-entry>+ Add entry</button></div>'
  +'<div class="activity-search-row"><label class="activity-search"><span>⌕</span><input id="activitySearch" type="search" placeholder="Search merchant, note, account or amount…" autocomplete="off" value="'+esc(s.q)+'"></label><button type="button" class="activity-filter-toggle" id="activityFilterToggle" aria-expanded="false" aria-controls="activityAdvancedFilters">☷ <span>Filters</span><i id="activityFilterBadge" hidden>0</i></button></div>'
  +'<div class="act-periods" role="group" aria-label="Period">'+ACT_PERIODS.map(p=>'<button type="button" data-activity-date="'+p[0]+'">'+p[1]+'</button>').join('')+'</div>'
  +'<div class="activity-quick-filters" role="group" aria-label="Transaction type"><button type="button" data-activity-kind="all">All</button><button type="button" data-activity-kind="income">Money in</button><button type="button" data-activity-kind="expense">Money out</button><button type="button" data-activity-kind="transfer">Transfers</button><button type="button" data-activity-kind="investment">Investments</button></div>'
  +'<details class="activity-advanced" id="activityAdvancedFilters"><summary>More filters</summary><div class="activity-filter-fields"><label>Transaction type<select id="activityKind">'+kinds.map(k=>opt(k[0],k[1],s.kind)).join('')+'</select></label><label>Account<select id="activityAccount">'+opt('all','All accounts',s.account)+opt('__none','No account linked',s.account)+accountsList.map(a=>opt(a,a,s.account)).join('')+'</select></label><div class="activity-date-presets"><span>Quick dates</span><div><button type="button" data-activity-date="today">Today</button><button type="button" data-activity-date="7">7 days</button><button type="button" data-activity-date="30">30 days</button></div></div><div class="activity-date-inputs"><label>From<input id="activityFrom" type="date" value="'+esc(init[0])+'"></label><label>To<input id="activityTo" type="date" value="'+esc(init[1])+'"></label></div><div class="activity-filter-actions"><button type="button" class="ghost" id="activityReset">Reset</button><button type="button" class="primary" id="activityApply">Apply filters</button></div></div></details>'
  +'<div id="activityActiveFilters" class="activity-active-filters"></div><button type="button" id="activityClearAll" class="activity-clear-all" hidden>Clear all filters</button>'
  +'<div id="activitySummary" class="act-summary" aria-live="polite"></div><div id="activityRows" class="activity-list"></div></section>';
}
function renderView(view){activeView=view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));updateNav(view);$('sourceNav').classList.remove('more-open');const target=$('viewContent');if(!target)return;const banks=sourceSections.filter(isBankBalanceSection);const other=sourceSections.filter(s=>!isBankBalanceSection(s)&&!isInvestmentRecord(s));$('viewTitle').textContent=(views.find(v=>v[0]===view)||views[0])[1];const viewEyebrow=$('viewTitle').previousElementSibling;if(viewEyebrow)viewEyebrow.textContent=VIEW_GROUPS[view]||'YOUR MONEY';if(view==='more'){target.innerHTML=moreHubHtml()}else if(view==='rewards'){target.innerHTML='<div id="rewardsBox">'+rewardsPageHtml(rewardsData)+'</div>';loadRewards()}else if(view==='interest'){target.innerHTML=interestViewHtml()+(user?.role==='admin'?'<div id="interestSources"></div>':'');loadInterestSources()}else if(view==='alerts'){target.innerHTML=alertsHtml()}else if(view==='subscriptions'){target.innerHTML=subscriptionsHtml()}else if(view==='stock-advisor'){target.innerHTML=stockAdvisorHtml();loadStockAdvisor()}else if(view==='data-quality'){target.innerHTML='<div id="dataQuality"><p class="muted">Checking data quality…</p></div>';loadDataQuality()}else if(view==='angel-one'){target.innerHTML=angelOneHtml()}else if(view==='bank-detail'){target.innerHTML='<button type="button" class="ghost" id="backToBanks">← Back to accounts</button><h3 class="group-title">'+esc(activeBank)+' · Account details</h3><div id="bankDetail"><p class="muted">Loading account details…</p></div>';loadBankDetail(activeBank)}else if(view==='overview'){target.innerHTML=alertsBannerHtml()+analyticsHtml()+'<div class="overview-grid"><article class="mini-card"><small>CASH BALANCE</small><strong>'+money((historicalCashBalances().slice(-1)[0]||{}).total||0)+'</strong><span>Latest saved bank balance snapshot</span></article><article class="mini-card"><small>LIABILITIES</small><strong>'+money(sumTotals(spendOf('liability')))+'</strong><span>Recorded liability entries</span></article><article class="mini-card"><small>BANK ACCOUNTS</small><strong>'+banks.length+'</strong></article><article class="mini-card"><small>OTHER RECORDS</small><strong>'+other.length+'</strong></article><article class="mini-card"><small>LIVE TRANSACTIONS</small><strong>'+transactionTotalCount()+'</strong></article></div><p class="muted">Open Banks to view account balances and details.</p>'}else if(view==='banks'){target.innerHTML=liveBankCardsHtml()||(banks.length?bankCards(banks):'<p class="muted">No bank balance records found.</p>')}else if(view==='other'){target.innerHTML=recordsPageHtml()}else if(view==='investments'){target.innerHTML=investmentsPageHtml()}else if(view==='bank-detail'){const key=activeBank||'Bank';$('viewTitle').textContent=key;target.innerHTML='<button type="button" class="back-button" id="backToBanks">← All accounts</button><h3 class="group-title">'+esc(key)+' account details</h3>'+accountRecords(key).map(sectionHtml).join('')}else if(view==='transactions'){target.innerHTML=activitiesHtml();activityRowsHtml()}const bindSpendCard=(selector,isMonth)=>{const card=target.querySelector(selector);if(card){const toggle=()=>{if(isMonth)showMonthSpend=!showMonthSpend;else showCategorySpend=!showCategorySpend;renderView('overview')};card.addEventListener('click',toggle);card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}})}};bindSpendCard('[data-spend-breakdown]',false);bindSpendCard('[data-month-spend-breakdown]',true)}
document.addEventListener('click',e=>{const alertButton=e.target.closest('.dashboard-alert-banner[data-view]');if(!alertButton)return;e.preventDefault();e.stopImmediatePropagation();renderView(alertButton.dataset.view)},true);
$('viewContent').addEventListener('click',e=>{const b=e.target.closest('button[data-view]');if(b&&$('viewContent').contains(b)){renderView(b.dataset.view)}});
$('viewContent').addEventListener('input',e=>{if(e.target.matches('#activitySearch'))activityRowsHtml();if(e.target.matches('#recordsSearch')){recordsState={...recordsState,q:e.target.value};const l=$('recordsList');if(l)l.innerHTML=recordsListHtml(recordsItems())}});
$('viewContent').addEventListener('click',e=>{const chip=e.target.closest('[data-record-type]');if(!chip)return;recordsState={...recordsState,type:chip.dataset.recordType};renderView('other')});
$('viewContent').addEventListener('change',e=>{if(e.target.matches('#activityKind,#activityAccount,#activityFrom,#activityTo'))activityRowsHtml()});
$('viewContent').addEventListener('click',e=>{if(e.target.closest('[data-action="logout"]')){signOut();return}if(e.target.closest('[data-action="reset-password"]')){ownerResetPassword();return}const deleteButton=e.target.closest('.delete[data-id]');if(deleteButton){const id=deleteButton.dataset.id;if(confirm('Delete this ledger entry?'))api('/api/ledger?id='+encodeURIComponent(id),{method:'DELETE'}).then(async()=>{await loadDashboard();renderView(activeView)}).catch(err=>{$('globalMsg').textContent=err.message});return}const quickKind=e.target.closest('[data-activity-kind]');if(quickKind){const kind=quickKind.dataset.activityKind;const select=$('activityKind');if(select)select.value=kind;document.querySelectorAll('[data-activity-kind]').forEach(b=>b.classList.toggle('active',b===quickKind));activityRowsHtml();return}if(e.target.closest('#activityMore')){activityState.shown+=60;activityRowsHtml();return}const datePreset=e.target.closest('[data-activity-date]');if(datePreset){const r=activityPresetRange(datePreset.dataset.activityDate);const f=$('activityFrom'),t=$('activityTo');if(f)f.value=r[0];if(t)t.value=r[1];activityRowsHtml();return}if(e.target.closest('#activityFilterToggle')){const panel=$('activityAdvancedFilters'),btn=$('activityFilterToggle');if(panel){panel.open=!panel.open;btn?.setAttribute('aria-expanded',String(panel.open))}return}if(e.target.closest('#activityApply')){const panel=$('activityAdvancedFilters');if(panel)panel.open=false;$('activityFilterToggle')?.setAttribute('aria-expanded','false');activityRowsHtml();return}if(e.target.closest('[data-clear-filter]')){const id=e.target.closest('[data-clear-filter]').dataset.clearFilter;if(id==='activityDate'){['activityFrom','activityTo'].forEach(k=>{if($(k))$(k).value=''})}else if($(id))$(id).value=id==='activityKind'?'all':'';activityRowsHtml();return}if(e.target.closest('#activityClearAll')||e.target.closest('#activityReset')){['activitySearch','activityFrom','activityTo'].forEach(id=>{if($(id))$(id).value=''});['activityKind','activityAccount'].forEach(id=>{if($(id))$(id).value='all'});document.querySelectorAll('[data-activity-kind]').forEach(b=>b.classList.toggle('active',b.dataset.activityKind==='all'));const panel=$('activityAdvancedFilters');if(panel)panel.open=false;$('activityFilterToggle')?.setAttribute('aria-expanded','false');activityRowsHtml();return}if(e.target.closest('#interestRefresh')){loadDashboard().then(()=>renderView('interest')).catch(err=>{$('globalMsg').textContent=err.message});return}if(e.target.closest('[data-angel-refresh]')){loadAngelOne();return}if(e.target.closest('[data-stock-advisor-refresh]')){loadStockAdvisor();return}const acceptIssue=e.target.closest('[data-accept-issue]');if(acceptIssue){acceptDataIssue(acceptIssue.dataset.acceptIssue);return}const point=e.target.closest('.chart-point');if(point){showChartTooltip(point);return}if(e.target.closest('[data-add-entry]')){openEntryForm();return}if(e.target.closest('[data-load-more-tx]')){loadRemainingTransactions().catch(err=>{$('globalMsg').textContent=err.message});return}const paid=e.target.closest('[data-bill-paid]');if(paid){const id=paid.dataset.billPaid;api('/api/planned-bills',{method:'PATCH',body:JSON.stringify({id,status:'paid'})}).then(()=>{plannedBills=plannedBills.filter(b=>b.id!==id);renderView(activeView)}).catch(err=>{$('globalMsg').textContent=err.message});return}if(e.target.closest('[data-spend-close]')){showCategorySpend=false;showMonthSpend=false;renderView('overview');return}const card=e.target.closest('[data-bank]');if(card){openBank(card.dataset.bank);return}if(e.target.closest('#backToBanks'))renderView('banks')});
$('menuNav').addEventListener('click',e=>{if(e.target.closest('#toolsToggle')){setToolsMenu($('toolsMenu').classList.contains('hidden'));return}const b=e.target.closest('[data-view]');if(b)renderView(b.dataset.view)});
document.addEventListener('click',e=>{if(!e.target.closest('.nav-tools'))setToolsMenu(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('toolsMenu')?.classList.contains('hidden')){setToolsMenu(false);$('toolsToggle')?.focus()}});
$('mobileNav').addEventListener('click',e=>{const b=e.target.closest('button[data-view]');if(b)renderView(b.dataset.view)});

async function signOut(){try{await api('/api/auth?action=logout',{method:'POST',body:'{}'});}finally{location.reload()}}
$('cancel').onclick=()=>$('txForm').classList.add('hidden');
$('txForm').onsubmit=async e=>{e.preventDefault();$('txMsg').textContent='';try{await api('/api/ledger',{method:'POST',body:JSON.stringify({kind:$('kind').value,amount:$('amount').value,category:$('category').value,account:$('account').value,date:$('date').value,description:$('description').value})});e.target.reset();$('txForm').classList.add('hidden');await load();renderView(activeView)}catch(x){$('txMsg').textContent=x.message}};
